#!/usr/bin/env node
// Builds the two generated files the cloud sync needs, from the same sources the rest of
// BossListers uses, so the cloud and this computer can never follow different rules:
//   supabase/functions/ebay-sync/plan.mjs     from lib/inventoryCountPlan.js
//   supabase/functions/ebay-sync/config.json  from config/inventory-sync.json
//
//   node scripts/build-cloud-sync.js          write the files
//   node scripts/build-cloud-sync.js --check  exit 1 if they are out of date (used by the tests)
const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const OUT_DIR = path.join(ROOT, "supabase", "functions", "ebay-sync");
const HEADER = "// GENERATED by scripts/build-cloud-sync.js from lib/inventoryCountPlan.js. Do not edit.\n";

function buildPlan() {
  const source = fs.readFileSync(path.join(ROOT, "lib", "inventoryCountPlan.js"), "utf8").replace(/\r\n/g, "\n");
  const exportLine = /^module\.exports = (\{[^}]*\});\s*$/m;
  if (!exportLine.test(source)) throw new Error("lib/inventoryCountPlan.js: the module.exports line was not found");
  return HEADER + source.replace(exportLine, "export $1;") ;
}

function buildConfig() {
  const config = JSON.parse(fs.readFileSync(path.join(ROOT, "config", "inventory-sync.json"), "utf8"));
  if (!config.ownerTenantId) throw new Error("config/inventory-sync.json: ownerTenantId is missing");
  const out = { ownerTenantId: config.ownerTenantId, digitalSkus: config.digitalSkus || [], ebayWritesEnabled: config.ebayWritesEnabled === true };
  return JSON.stringify(out, null, 2) + "\n";
}

function build() {
  return { "plan.mjs": buildPlan(), "config.json": buildConfig() };
}

function main() {
  const files = build();
  const check = process.argv.includes("--check");
  let stale = false;
  for (const [name, content] of Object.entries(files)) {
    const file = path.join(OUT_DIR, name);
    const current = fs.existsSync(file) ? fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n") : null;
    if (current === content) continue;
    stale = true;
    if (check) console.error(`out of date: supabase/functions/ebay-sync/${name}`);
    else { fs.writeFileSync(file, content, "utf8"); console.log(`wrote supabase/functions/ebay-sync/${name}`); }
  }
  if (check && stale) process.exit(1);
  if (!stale) console.log("cloud sync files are up to date");
}

module.exports = { build };

if (require.main === module) main();
